  Object.assign(D.en, {"mic.link": "Mic not working? Get help", "mic.title": "Parley can't hear you?", "mic.test": "Test my mic", "mic.testing": "Listening for 7 seconds. Say something.", "mic.heard": "Heard you:", "mic.silent": "Heard nothing. Try the steps above, then test again.", "mic.testblocked": "The microphone is blocked. Follow the first steps above.", "mic.blocked": "Microphone blocked. Tap here for the fix.", "mic.nomic": "No microphone found.", "mic.found.inapp": "You are inside another app's browser (Instagram, Facebook, TikTok and similar). These block the microphone for speech.", "mic.found.denied": "This site is blocked from using your microphone.", "mic.found.nosr": "This browser can't turn speech into text.", "mic.found.generic": "Go through these in order. Most fixes take ten seconds.", "mic.s.inapp": "Open Parley in <b>Chrome</b> instead: tap the <b>⋮</b> or <b>···</b> menu, then <b>Open in browser</b> (or copy getparley.vercel.app into Chrome).", "mic.s.nosr": "Use <b>Chrome</b> on Android or <b>Safari</b> on iPhone. Other browsers don't support live speech.", "mic.s.browser": "For the most reliable speech, open Parley in <b>Chrome</b> (Android) or <b>Safari</b> (iPhone).", "mic.s.blocked": "In Chrome, tap the <b>lock icon</b> next to the address, then <b>Permissions</b>, set <b>Microphone</b> to <b>Allow</b>. Then close the tab and open Parley again.", "mic.s.blockedios": "On iPhone: <b>Settings</b>, <b>Safari</b>, <b>Microphone</b>, set to <b>Ask</b> or <b>Allow</b>. Then reload Parley.", "mic.s.prompt": "When the browser asks to use the microphone, tap <b>Allow</b>. If you don't see the question, reload the page.", "mic.s.os": "Android settings: <b>Settings</b>, <b>Privacy</b> (or Apps), <b>Permissions</b>, <b>Microphone</b>, make sure <b>Chrome</b> is allowed. Also check the microphone switch in the quick settings panel isn't off.", "mic.s.google": "Settings, <b>Apps</b>, <b>Speech Recognition and Synthesis from Google</b> (also the <b>Google</b> app): both must be enabled and updated in the Play Store.", "mic.s.ios": "If Siri dictation is off: <b>Settings</b>, <b>General</b>, <b>Keyboard</b>, turn on <b>Enable Dictation</b>.", "mic.s.other": "Close other apps that might be using the mic (calls, voice notes, screen recorders), then fully close Chrome and reopen Parley. Tap <b>Test my mic</b> below to check.", "mic.all": "Still not working? See every fix"});
  Object.assign(D.es, {"mic.link": "¿No funciona el micrófono? Ayuda", "mic.title": "¿Parley no te escucha?", "mic.test": "Probar mi micrófono", "mic.testing": "Escuchando 7 segundos. Di algo.", "mic.heard": "Te escuché:", "mic.silent": "No escuché nada. Prueba los pasos de arriba y vuelve a probar.", "mic.testblocked": "El micrófono está bloqueado. Sigue los primeros pasos.", "mic.blocked": "Micrófono bloqueado. Toca aquí para arreglarlo.", "mic.nomic": "No se encontró micrófono.", "mic.found.inapp": "Estás dentro del navegador de otra app (Instagram, Facebook, TikTok y similares). Esos bloquean el micrófono para voz.", "mic.found.denied": "Este sitio no tiene permiso para usar tu micrófono.", "mic.found.nosr": "Este navegador no puede convertir voz en texto.", "mic.found.generic": "Sigue estos pasos en orden. La mayoría se arreglan en diez segundos.", "mic.s.inapp": "Abre Parley en <b>Chrome</b>: toca el menú <b>⋮</b> o <b>···</b> y luego <b>Abrir en el navegador</b> (o copia getparley.vercel.app en Chrome).", "mic.s.nosr": "Usa <b>Chrome</b> en Android o <b>Safari</b> en iPhone. Otros navegadores no admiten voz en vivo.", "mic.s.browser": "Para que la voz funcione mejor, abre Parley en <b>Chrome</b> (Android) o <b>Safari</b> (iPhone).", "mic.s.blocked": "En Chrome, toca el <b>candado</b> junto a la dirección, luego <b>Permisos</b> y pon <b>Micrófono</b> en <b>Permitir</b>. Cierra la pestaña y abre Parley otra vez.", "mic.s.blockedios": "En iPhone: <b>Ajustes</b>, <b>Safari</b>, <b>Micrófono</b>, pon <b>Preguntar</b> o <b>Permitir</b>. Luego recarga Parley.", "mic.s.prompt": "Cuando el navegador pida usar el micrófono, toca <b>Permitir</b>. Si no ves la pregunta, recarga la página.", "mic.s.os": "Ajustes de Android: <b>Ajustes</b>, <b>Privacidad</b> (o Apps), <b>Permisos</b>, <b>Micrófono</b>, y confirma que <b>Chrome</b> tiene permiso. Revisa también que el interruptor del micrófono en el panel rápido no esté apagado.", "mic.s.google": "Ajustes, <b>Apps</b>, <b>Reconocimiento y síntesis de voz de Google</b> (y la app de <b>Google</b>): ambas deben estar activadas y actualizadas en Play Store.", "mic.s.ios": "Si el dictado está apagado: <b>Ajustes</b>, <b>General</b>, <b>Teclado</b>, activa <b>Dictado</b>.", "mic.s.other": "Cierra otras apps que usen el micrófono (llamadas, notas de voz, grabadores de pantalla), cierra Chrome por completo y abre Parley. Toca <b>Probar mi micrófono</b> para comprobar.", "mic.all": "¿Sigue sin funcionar? Ver todas las soluciones"});
  Object.assign(D.pt, {"mic.link": "O microfone não funciona? Ajuda", "mic.all": "Ainda não funciona? Ver todas as soluções", "mic.title": "O Parley não está te ouvindo?", "mic.test": "Testar meu microfone", "mic.testing": "Ouvindo por 7 segundos. Diga algo.", "mic.heard": "Ouvi você:", "mic.silent": "Não ouvi nada. Tente os passos acima e teste de novo.", "mic.testblocked": "O microfone está bloqueado. Siga os primeiros passos.", "mic.blocked": "Microfone bloqueado. Toque aqui para resolver.", "mic.nomic": "Nenhum microfone encontrado.", "mic.found.inapp": "Você está dentro do navegador de outro app (Instagram, Facebook, TikTok e similares). Eles bloqueiam o microfone para voz.", "mic.found.denied": "Este site não tem permissão para usar seu microfone.", "mic.found.nosr": "Este navegador não consegue transformar voz em texto.", "mic.found.generic": "Siga estes passos em ordem. A maioria se resolve em dez segundos.", "mic.s.inapp": "Abra o Parley no <b>Chrome</b>: toque no menu <b>⋮</b> ou <b>···</b> e depois em <b>Abrir no navegador</b> (ou copie getparley.vercel.app no Chrome).", "mic.s.nosr": "Use o <b>Chrome</b> no Android ou o <b>Safari</b> no iPhone. Outros navegadores não suportam voz ao vivo.", "mic.s.browser": "Para a voz funcionar melhor, abra o Parley no <b>Chrome</b> (Android) ou no <b>Safari</b> (iPhone).", "mic.s.blocked": "No Chrome, toque no <b>cadeado</b> ao lado do endereço, depois em <b>Permissões</b> e deixe <b>Microfone</b> em <b>Permitir</b>. Feche a aba e abra o Parley de novo.", "mic.s.blockedios": "No iPhone: <b>Ajustes</b>, <b>Safari</b>, <b>Microfone</b>, deixe em <b>Perguntar</b> ou <b>Permitir</b>. Depois recarregue o Parley.", "mic.s.prompt": "Quando o navegador pedir para usar o microfone, toque em <b>Permitir</b>. Se a pergunta não aparecer, recarregue a página.", "mic.s.os": "Configurações do Android: <b>Configurações</b>, <b>Privacidade</b> (ou Apps), <b>Permissões</b>, <b>Microfone</b>, e confirme que o <b>Chrome</b> tem permissão. Veja também se o botão do microfone no painel rápido não está desligado.", "mic.s.google": "Configurações, <b>Apps</b>, <b>Reconhecimento e síntese de fala do Google</b> (e o app <b>Google</b>): ambos precisam estar ativados e atualizados na Play Store.", "mic.s.ios": "Se o ditado estiver desligado: <b>Ajustes</b>, <b>Geral</b>, <b>Teclado</b>, ative <b>Ditado</b>.", "mic.s.other": "Feche outros apps que usem o microfone (chamadas, áudios, gravadores de tela), feche o Chrome por completo e abra o Parley. Toque em <b>Testar meu microfone</b> para conferir."});
  Object.assign(D.fr, {"mic.link": "Le micro ne marche pas ? Aide", "mic.all": "Ça ne marche toujours pas ? Voir toutes les solutions", "mic.title": "Parley ne vous entend pas ?", "mic.test": "Tester mon micro", "mic.testing": "J'écoute pendant 7 secondes. Dites quelque chose.", "mic.heard": "Je vous ai entendu :", "mic.silent": "Rien entendu. Essayez les étapes ci-dessus, puis retestez.", "mic.testblocked": "Le micro est bloqué. Suivez les premières étapes.", "mic.blocked": "Micro bloqué. Touchez ici pour le réparer.", "mic.nomic": "Aucun micro trouvé.", "mic.found.inapp": "Vous êtes dans le navigateur d'une autre appli (Instagram, Facebook, TikTok, etc.). Ils bloquent le micro pour la voix.", "mic.found.denied": "Ce site n'a pas l'autorisation d'utiliser votre micro.", "mic.found.nosr": "Ce navigateur ne peut pas transformer la voix en texte.", "mic.found.generic": "Suivez ces étapes dans l'ordre. La plupart se règlent en dix secondes.", "mic.s.inapp": "Ouvrez Parley dans <b>Chrome</b> : touchez le menu <b>⋮</b> ou <b>···</b>, puis <b>Ouvrir dans le navigateur</b> (ou copiez getparley.vercel.app dans Chrome).", "mic.s.nosr": "Utilisez <b>Chrome</b> sur Android ou <b>Safari</b> sur iPhone. Les autres navigateurs ne gèrent pas la voix en direct.", "mic.s.browser": "Pour une voix plus fiable, ouvrez Parley dans <b>Chrome</b> (Android) ou <b>Safari</b> (iPhone).", "mic.s.blocked": "Dans Chrome, touchez le <b>cadenas</b> à côté de l'adresse, puis <b>Autorisations</b>, et réglez <b>Micro</b> sur <b>Autoriser</b>. Fermez l'onglet puis rouvrez Parley.", "mic.s.blockedios": "Sur iPhone : <b>Réglages</b>, <b>Safari</b>, <b>Micro</b>, choisissez <b>Demander</b> ou <b>Autoriser</b>. Puis rechargez Parley.", "mic.s.prompt": "Quand le navigateur demande d'utiliser le micro, touchez <b>Autoriser</b>. Si la question n'apparaît pas, rechargez la page.", "mic.s.os": "Réglages Android : <b>Paramètres</b>, <b>Confidentialité</b> (ou Applis), <b>Autorisations</b>, <b>Micro</b>, et vérifiez que <b>Chrome</b> est autorisé. Vérifiez aussi que l'interrupteur du micro dans les réglages rapides n'est pas coupé.", "mic.s.google": "Paramètres, <b>Applis</b>, <b>Reconnaissance et synthèse vocales Google</b> (et l'appli <b>Google</b>) : les deux doivent être activées et à jour dans le Play Store.", "mic.s.ios": "Si la dictée est désactivée : <b>Réglages</b>, <b>Général</b>, <b>Clavier</b>, activez <b>Dictée</b>.", "mic.s.other": "Fermez les autres applis qui utilisent le micro (appels, mémos vocaux, enregistreurs d'écran), fermez complètement Chrome et rouvrez Parley. Touchez <b>Tester mon micro</b> pour vérifier."});
  Object.assign(D.de, {"mic.link": "Mikrofon funktioniert nicht? Hilfe", "mic.all": "Immer noch nicht? Alle Lösungen anzeigen", "mic.title": "Parley hört dich nicht?", "mic.test": "Mein Mikrofon testen", "mic.testing": "Ich höre 7 Sekunden zu. Sag etwas.", "mic.heard": "Ich habe dich gehört:", "mic.silent": "Nichts gehört. Probiere die Schritte oben und teste erneut.", "mic.testblocked": "Das Mikrofon ist blockiert. Folge den ersten Schritten.", "mic.blocked": "Mikrofon blockiert. Tippe hier für die Lösung.", "mic.nomic": "Kein Mikrofon gefunden.", "mic.found.inapp": "Du bist im Browser einer anderen App (Instagram, Facebook, TikTok und ähnliche). Diese blockieren das Mikrofon für Sprache.", "mic.found.denied": "Diese Seite darf dein Mikrofon nicht nutzen.", "mic.found.nosr": "Dieser Browser kann Sprache nicht in Text umwandeln.", "mic.found.generic": "Gehe diese Schritte der Reihe nach durch. Die meisten dauern zehn Sekunden.", "mic.s.inapp": "Öffne Parley in <b>Chrome</b>: tippe auf das Menü <b>⋮</b> oder <b>···</b>, dann auf <b>Im Browser öffnen</b> (oder kopiere getparley.vercel.app in Chrome).", "mic.s.nosr": "Nutze <b>Chrome</b> auf Android oder <b>Safari</b> auf dem iPhone. Andere Browser unterstützen Live-Sprache nicht.", "mic.s.browser": "Für zuverlässigere Sprache öffne Parley in <b>Chrome</b> (Android) oder <b>Safari</b> (iPhone).", "mic.s.blocked": "Tippe in Chrome auf das <b>Schloss</b> neben der Adresse, dann auf <b>Berechtigungen</b> und stelle <b>Mikrofon</b> auf <b>Zulassen</b>. Schließe den Tab und öffne Parley neu.", "mic.s.blockedios": "Auf dem iPhone: <b>Einstellungen</b>, <b>Safari</b>, <b>Mikrofon</b>, auf <b>Fragen</b> oder <b>Erlauben</b> stellen. Dann Parley neu laden.", "mic.s.prompt": "Wenn der Browser nach dem Mikrofon fragt, tippe auf <b>Zulassen</b>. Erscheint die Frage nicht, lade die Seite neu.", "mic.s.os": "Android-Einstellungen: <b>Einstellungen</b>, <b>Datenschutz</b> (oder Apps), <b>Berechtigungen</b>, <b>Mikrofon</b>, und prüfe, dass <b>Chrome</b> erlaubt ist. Prüfe auch, dass der Mikrofon-Schalter in den Schnelleinstellungen nicht aus ist.", "mic.s.google": "Einstellungen, <b>Apps</b>, <b>Spracherkennung und -ausgabe von Google</b> (und die <b>Google</b>-App): beide müssen aktiviert und im Play Store aktuell sein.", "mic.s.ios": "Wenn Diktieren aus ist: <b>Einstellungen</b>, <b>Allgemein</b>, <b>Tastatur</b>, <b>Diktierfunktion aktivieren</b>.", "mic.s.other": "Schließe andere Apps, die das Mikrofon nutzen (Anrufe, Sprachnachrichten, Bildschirmaufnahme), beende Chrome komplett und öffne Parley neu. Tippe auf <b>Mein Mikrofon testen</b>, um zu prüfen."});
  Object.assign(D.it, {"mic.link": "Il microfono non funziona? Aiuto", "mic.all": "Ancora niente? Vedi tutte le soluzioni", "mic.title": "Parley non ti sente?", "mic.test": "Prova il mio microfono", "mic.testing": "Ascolto per 7 secondi. Di' qualcosa.", "mic.heard": "Ti ho sentito:", "mic.silent": "Non ho sentito nulla. Prova i passaggi sopra e riprova.", "mic.testblocked": "Il microfono è bloccato. Segui i primi passaggi.", "mic.blocked": "Microfono bloccato. Tocca qui per risolvere.", "mic.nomic": "Nessun microfono trovato.", "mic.found.inapp": "Sei nel browser di un'altra app (Instagram, Facebook, TikTok e simili). Bloccano il microfono per la voce.", "mic.found.denied": "Questo sito non ha il permesso di usare il microfono.", "mic.found.nosr": "Questo browser non può trasformare la voce in testo.", "mic.found.generic": "Segui questi passaggi in ordine. La maggior parte si risolve in dieci secondi.", "mic.s.inapp": "Apri Parley in <b>Chrome</b>: tocca il menu <b>⋮</b> o <b>···</b>, poi <b>Apri nel browser</b> (oppure copia getparley.vercel.app in Chrome).", "mic.s.nosr": "Usa <b>Chrome</b> su Android o <b>Safari</b> su iPhone. Gli altri browser non supportano la voce dal vivo.", "mic.s.browser": "Per una voce più affidabile, apri Parley in <b>Chrome</b> (Android) o <b>Safari</b> (iPhone).", "mic.s.blocked": "In Chrome tocca il <b>lucchetto</b> accanto all'indirizzo, poi <b>Autorizzazioni</b>, e imposta <b>Microfono</b> su <b>Consenti</b>. Chiudi la scheda e riapri Parley.", "mic.s.blockedios": "Su iPhone: <b>Impostazioni</b>, <b>Safari</b>, <b>Microfono</b>, imposta <b>Chiedi</b> o <b>Consenti</b>. Poi ricarica Parley.", "mic.s.prompt": "Quando il browser chiede il microfono, tocca <b>Consenti</b>. Se la richiesta non compare, ricarica la pagina.", "mic.s.os": "Impostazioni Android: <b>Impostazioni</b>, <b>Privacy</b> (o App), <b>Autorizzazioni</b>, <b>Microfono</b>, e verifica che <b>Chrome</b> sia consentito. Controlla anche che l'interruttore del microfono nelle impostazioni rapide non sia spento.", "mic.s.google": "Impostazioni, <b>App</b>, <b>Riconoscimento e sintesi vocale di Google</b> (e l'app <b>Google</b>): entrambe devono essere attive e aggiornate dal Play Store.", "mic.s.ios": "Se la dettatura è disattivata: <b>Impostazioni</b>, <b>Generali</b>, <b>Tastiera</b>, attiva <b>Dettatura</b>.", "mic.s.other": "Chiudi le altre app che usano il microfono (chiamate, note vocali, registratori schermo), chiudi del tutto Chrome e riapri Parley. Tocca <b>Prova il mio microfono</b> per verificare."});
  Object.assign(D.ko, {"mic.link": "마이크가 안 되나요? 도움말", "mic.all": "아직도 안 되나요? 모든 해결 방법 보기", "mic.title": "Parley가 목소리를 못 듣나요?", "mic.test": "마이크 테스트", "mic.testing": "7초 동안 듣습니다. 말해 보세요.", "mic.heard": "들렸어요:", "mic.silent": "아무것도 들리지 않았어요. 위 단계를 시도한 뒤 다시 테스트하세요.", "mic.testblocked": "마이크가 차단되어 있어요. 첫 번째 단계를 따라 하세요.", "mic.blocked": "마이크가 차단되었어요. 여기를 눌러 해결하세요.", "mic.nomic": "마이크를 찾을 수 없어요.", "mic.found.inapp": "다른 앱의 내장 브라우저(인스타그램, 페이스북, 틱톡 등) 안에 있어요. 이런 브라우저는 음성용 마이크를 막습니다.", "mic.found.denied": "이 사이트는 마이크 사용이 허용되지 않았어요.", "mic.found.nosr": "이 브라우저는 음성을 텍스트로 바꿀 수 없어요.", "mic.found.generic": "순서대로 따라 해 보세요. 대부분 10초면 해결됩니다.", "mic.s.inapp": "<b>Chrome</b>에서 Parley를 여세요: <b>⋮</b> 또는 <b>···</b> 메뉴를 누르고 <b>브라우저에서 열기</b>를 선택하세요 (또는 getparley.vercel.app을 Chrome에 붙여넣기).", "mic.s.nosr": "Android는 <b>Chrome</b>, iPhone은 <b>Safari</b>를 사용하세요. 다른 브라우저는 실시간 음성을 지원하지 않습니다.", "mic.s.browser": "더 안정적인 음성 인식을 위해 <b>Chrome</b>(Android) 또는 <b>Safari</b>(iPhone)에서 Parley를 여세요.", "mic.s.blocked": "Chrome에서 주소 옆 <b>자물쇠 아이콘</b>을 누르고 <b>권한</b>에서 <b>마이크</b>를 <b>허용</b>으로 바꾸세요. 탭을 닫고 Parley를 다시 여세요.", "mic.s.blockedios": "iPhone: <b>설정</b>, <b>Safari</b>, <b>마이크</b>를 <b>묻기</b> 또는 <b>허용</b>으로 설정한 뒤 Parley를 새로고침하세요.", "mic.s.prompt": "브라우저가 마이크 사용을 물으면 <b>허용</b>을 누르세요. 질문이 보이지 않으면 페이지를 새로고침하세요.", "mic.s.os": "Android 설정: <b>설정</b>, <b>개인정보 보호</b>(또는 앱), <b>권한</b>, <b>마이크</b>에서 <b>Chrome</b>이 허용되어 있는지 확인하세요. 빠른 설정 패널의 마이크 스위치가 꺼져 있지 않은지도 확인하세요.", "mic.s.google": "설정, <b>앱</b>, <b>Google 음성 인식 및 합성</b>(그리고 <b>Google</b> 앱): 둘 다 사용 설정되어 있고 Play 스토어에서 최신 상태여야 합니다.", "mic.s.ios": "받아쓰기가 꺼져 있다면: <b>설정</b>, <b>일반</b>, <b>키보드</b>, <b>받아쓰기 활성화</b>를 켜세요.", "mic.s.other": "마이크를 쓰는 다른 앱(통화, 음성 메모, 화면 녹화)을 닫고, Chrome을 완전히 종료한 뒤 Parley를 다시 여세요. <b>마이크 테스트</b>를 눌러 확인하세요."});
  Object.assign(D.ja, {"mic.link": "マイクが使えない？ ヘルプ", "mic.all": "まだ動かない？ すべての解決方法を見る", "mic.title": "Parleyに声が届いていませんか？", "mic.test": "マイクをテスト", "mic.testing": "7秒間聞き取ります。話してみてください。", "mic.heard": "聞こえました：", "mic.silent": "何も聞こえませんでした。上の手順を試してから、もう一度テストしてください。", "mic.testblocked": "マイクがブロックされています。最初の手順に従ってください。", "mic.blocked": "マイクがブロックされています。ここをタップして解決してください。", "mic.nomic": "マイクが見つかりません。", "mic.found.inapp": "他のアプリ内ブラウザ（Instagram、Facebook、TikTokなど）で開いています。これらは音声用のマイクをブロックします。", "mic.found.denied": "このサイトはマイクの使用が許可されていません。", "mic.found.nosr": "このブラウザは音声をテキストに変換できません。", "mic.found.generic": "順番に試してください。ほとんどは10秒で直ります。", "mic.s.inapp": "<b>Chrome</b>でParleyを開いてください：<b>⋮</b>または<b>···</b>メニューをタップし、<b>ブラウザで開く</b>を選びます（またはgetparley.vercel.appをChromeに貼り付け）。", "mic.s.nosr": "Androidは<b>Chrome</b>、iPhoneは<b>Safari</b>を使ってください。他のブラウザはライブ音声に対応していません。", "mic.s.browser": "音声をより確実に使うには、<b>Chrome</b>（Android）または<b>Safari</b>（iPhone）でParleyを開いてください。", "mic.s.blocked": "Chromeでアドレス横の<b>鍵アイコン</b>をタップし、<b>権限</b>から<b>マイク</b>を<b>許可</b>にします。タブを閉じてParleyを開き直してください。", "mic.s.blockedios": "iPhone：<b>設定</b>、<b>Safari</b>、<b>マイク</b>を<b>確認</b>または<b>許可</b>にして、Parleyを再読み込みしてください。", "mic.s.prompt": "ブラウザがマイクの使用を尋ねたら<b>許可</b>をタップしてください。表示されない場合はページを再読み込みしてください。", "mic.s.os": "Androidの設定：<b>設定</b>、<b>プライバシー</b>（またはアプリ）、<b>権限</b>、<b>マイク</b>で<b>Chrome</b>が許可されているか確認してください。クイック設定パネルのマイクスイッチがオフになっていないかも確認してください。", "mic.s.google": "設定、<b>アプリ</b>、<b>Google の音声認識と音声合成</b>（および<b>Google</b>アプリ）：両方が有効で、Playストアで最新である必要があります。", "mic.s.ios": "音声入力がオフの場合：<b>設定</b>、<b>一般</b>、<b>キーボード</b>、<b>音声入力を有効にする</b>をオンにしてください。", "mic.s.other": "マイクを使っている他のアプリ（通話、ボイスメモ、画面録画）を閉じ、Chromeを完全に終了してからParleyを開き直してください。<b>マイクをテスト</b>で確認できます。"});
  Object.assign(D.zh, {"mic.link": "麦克风不工作？获取帮助", "mic.all": "仍然不行？查看所有解决办法", "mic.title": "Parley 听不到你的声音？", "mic.test": "测试我的麦克风", "mic.testing": "正在听取 7 秒，请说点什么。", "mic.heard": "听到了：", "mic.silent": "什么也没听到。请试试上面的步骤，然后再测试。", "mic.testblocked": "麦克风被屏蔽了。请按前面的步骤操作。", "mic.blocked": "麦克风被屏蔽。点按此处查看解决办法。", "mic.nomic": "未找到麦克风。", "mic.found.inapp": "你正在其他应用的内置浏览器中（Instagram、Facebook、TikTok 等）。这些浏览器会屏蔽语音所需的麦克风。", "mic.found.denied": "此网站没有使用麦克风的权限。", "mic.found.nosr": "此浏览器无法将语音转成文字。", "mic.found.generic": "请按顺序操作，大多数问题十秒内就能解决。", "mic.s.inapp": "请在 <b>Chrome</b> 中打开 Parley：点按 <b>⋮</b> 或 <b>···</b> 菜单，然后选择<b>在浏览器中打开</b>（或把 getparley.vercel.app 复制到 Chrome）。", "mic.s.nosr": "Android 请用 <b>Chrome</b>，iPhone 请用 <b>Safari</b>。其他浏览器不支持实时语音。", "mic.s.browser": "为获得更稳定的语音效果，请在 <b>Chrome</b>（Android）或 <b>Safari</b>（iPhone）中打开 Parley。", "mic.s.blocked": "在 Chrome 中点按地址栏旁的<b>锁形图标</b>，进入<b>权限</b>，把<b>麦克风</b>设为<b>允许</b>。然后关闭标签页，重新打开 Parley。", "mic.s.blockedios": "iPhone：<b>设置</b>、<b>Safari</b>、<b>麦克风</b>，设为<b>询问</b>或<b>允许</b>，然后刷新 Parley。", "mic.s.prompt": "当浏览器询问是否使用麦克风时，点按<b>允许</b>。如果没有出现提示，请刷新页面。", "mic.s.os": "Android 设置：<b>设置</b>、<b>隐私</b>（或应用）、<b>权限</b>、<b>麦克风</b>，确认 <b>Chrome</b> 已被允许。同时检查快捷设置面板中的麦克风开关是否被关闭。", "mic.s.google": "设置、<b>应用</b>、<b>Google 语音识别和合成</b>（以及 <b>Google</b> 应用）：两者都必须启用，并在 Play 商店中保持最新。", "mic.s.ios": "如果听写已关闭：<b>设置</b>、<b>通用</b>、<b>键盘</b>，打开<b>启用听写</b>。", "mic.s.other": "关闭其他可能占用麦克风的应用（通话、语音备忘录、录屏），完全退出 Chrome，然后重新打开 Parley。点按<b>测试我的麦克风</b>进行检查。"});
